set feedback on echo on pagesize 100 linesize 200
whenever sqlerror continue
SELECT USER, (SELECT READ_ONLY FROM USER_USERS) RO FROM DUAL;
INSERT INTO APP_OWNER.SCRATCH VALUES (1);
UPDATE APP_OWNER.SCRATCH SET ID = 2;
DELETE FROM APP_OWNER.SCRATCH;
MERGE INTO APP_OWNER.SCRATCH s USING (SELECT 5 ID FROM DUAL) d ON (s.ID = d.ID) WHEN NOT MATCHED THEN INSERT VALUES (d.ID);
INSERT INTO APP_OWNER.T1 (ID, NAME) VALUES (9, 'x');
CREATE TABLE RO_T (ID NUMBER);
CREATE GLOBAL TEMPORARY TABLE RO_GTT (ID NUMBER);
CREATE PRIVATE TEMPORARY TABLE ORA$PTT_X (ID NUMBER);
SELECT APP_OWNER.WRITE_AUTON() FROM DUAL;
SELECT COUNT(*) FROM APP_OWNER.LOGT;
ALTER SESSION SET READ_ONLY = FALSE;
INSERT INTO APP_OWNER.SCRATCH VALUES (3);
SELECT APP_OWNER.WRITE_AUTON() FROM DUAL;
LOCK TABLE APP_OWNER.SCRATCH IN EXCLUSIVE MODE NOWAIT;
ROLLBACK;
LOCK TABLE APP_OWNER.T1 IN EXCLUSIVE MODE NOWAIT;
ROLLBACK;
SET TRANSACTION READ ONLY;
SELECT COUNT(*) FROM APP_OWNER.T1;
BEGIN INSERT INTO APP_OWNER.SCRATCH VALUES (4); END;
/
ROLLBACK;
SET TRANSACTION READ ONLY;
BEGIN EXECUTE IMMEDIATE 'SELECT 1 FROM DUAL'; INSERT INTO APP_OWNER.SCRATCH VALUES (6); END;
/
ROLLBACK;
SELECT UTL_HTTP.REQUEST('http://127.0.0.1:9/') FROM DUAL;
SELECT UTL_INADDR.GET_HOST_ADDRESS('localhost') FROM DUAL;
DECLARE f UTL_FILE.FILE_TYPE; BEGIN f := UTL_FILE.FOPEN('DATA_PUMP_DIR','x.txt','w'); END;
/
